from __future__ import annotations

import base64
import hashlib
from pathlib import Path

# Exact captured bytes from the interrupted shorter-hashes state and its
# retained Task 1 result / Task 2 blocker. These are test data, never loaded
# from the mutable worktree at runtime.
LEGACY_STATE_SHA256 = "b5fad609842013a1ca11017ec60e4ae45c042f92828cbf040c795129525b17e6"
LEGACY_RESULT_SHA256 = "c28a2796bbf25d74416fb1c63935b677a852e10ea23b3b2d52d1110a79519687"
LEGACY_BLOCKER_SHA256 = "fdd0bdb53786de16758a6b65347552798055580c2ee0f2fd07f0273fbd46feb2"
LEGACY_AUTHORITY_SHA = "e1ca2a523c5417687479c09ffc1bf6c1cc337763"
LEGACY_TASK1_BASE = "c8a5ea24821b0f984f4e9d7ddee38714d4409d16"
LEGACY_TASK2_BASE = "a8c598967e44bcabf12c38ef486d57059d2d23b5"

_STATE = ""
_RESULT = ""
_BLOCKER = ""


def _decode(value: str, expected: str) -> bytes:
    raw = base64.b64decode(value)
    if hashlib.sha256(raw).hexdigest() != expected:
        raise AssertionError("embedded legacy fixture digest mismatch")
    return raw


def write_legacy_fixture(root: Path) -> dict[str, bytes]:
    files = {
        "work/shorter-hashes/inner-loop/state.json": _decode(_STATE, LEGACY_STATE_SHA256),
        "work/shorter-hashes/inner-loop/results/1.json": _decode(_RESULT, LEGACY_RESULT_SHA256),
        "work/shorter-hashes/inner-loop/evidence/task-2-blocker.json": _decode(_BLOCKER, LEGACY_BLOCKER_SHA256),
        "work/shorter-hashes/traceability-accepted.json": (
            '{"schema":"ask-accepted-tests/v1","work_id":"shorter-hashes",'
            '"fixture_authority_sha":"' + LEGACY_AUTHORITY_SHA + '"}\n'
        ).encode(),
    }
    for name, raw in files.items():
        path = root / name
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_bytes(raw)
    return files
